import json, numpy as np
rows=[]
for line in open('lab_log.jsonl'):
    d=json.loads(line)
    if d['op']!='profile': continue
    for s in d['result']['segments']:
        rows.append((s['segment'],s['batch'],s['steps'],s['seconds']))
rows.sort()
seg=np.array([r[0] for r in rows]); B=np.array([r[1] for r in rows]); S=np.array([r[2] for r in rows])
def model(p,B,seg,s0=0):
    a,Bc0,g,al=p
    return a*(1+(Bc0*np.exp(g*(seg-s0))/B)**al)
def fit(mask,s0,als):
    best=None
    for al in als:
      for a in np.linspace(0.018,0.032,57):
        for Bc0 in np.exp(np.linspace(np.log(5),np.log(1500),80)):
          for g in np.linspace(-0.05,0.15,21):
            l=np.sum((np.log(model((a,Bc0,g,al),B[mask],seg[mask],s0))-np.log(S[mask]))**2)
            if best is None or l<best[0]: best=(l,(a,Bc0,g,al))
    return best
pre=seg<25; post=seg>=25
print("PRE by alpha:")
for al in [0.5,0.75,1.0,1.25,1.5,2.0]:
    print(al, fit(pre,0,[al]))
print("POST by alpha (s0=25):")
for al in [0.5,0.75,1.0,1.25,1.5,2.0]:
    print(al, fit(post,25,[al]))
# profile of pre loss over Bc0 with a,g free, alpha=1
print("PRE Bc profile (alpha=1):")
for Bc0 in [20,30,40,50,60,80,100]:
