        for g in np.linspace(-0.05,0.1,31):
            l=np.sum((np.log(model((a,Bc0,g,1.0),B[pre],seg[pre]))-np.log(S[pre]))**2)
            if best is None or l<best[0]: best=(l,a,g)
    print(Bc0,best, "rms%%=%.2f"%(100*np.sqrt(best[0]/pre.sum())))
